import sys

def main():
    data = sys.stdin.read().split()
    pos = 0
    def next_int():
        nonlocal pos
        v = int(data[pos])
        pos += 1
        return v
    def next_float():
        nonlocal pos
        v = float(data[pos])
        pos += 1
        return v

    try:
        m = next_int()
        l = next_int()
    except (IndexError, ValueError):
        print("Invalid input")
        return

    P = []
    for i in range(m):
        row = []
        for j in range(l):
            row.append(next_float())
        P.append(row)

    try:
        l2 = next_int()
        a = next_int()
        b = next_int()
    except (IndexError, ValueError):
        print("Invalid input")
        return

    T = []
    for t in range(l2):
        slice_ = []
        for j in range(a):
            row = []
            for k in range(b):
                row.append(next_float())
            slice_.append(row)
        T.append(slice_)

    if m == 0 or l == 0 or l2 == 0 or a == 0 or b == 0 or l != l2:
        print("Invalid input")
        return

    # Compute Q[i][j][k] = sum_t P[i][t]*T[t][j][k]
    # Q shape (m, a, b)
    Q = [[[0.0]*b for _ in range(a)] for _ in range(m)]
    for i in range(m):
        for j in range(a):
            for k in range(b):
                s = 0.0
                for t in range(l):
                    s += P[i][t] * T[t][j][k]
                Q[i][j][k] = s

    n = m * b
    R = [[0.0]*n for _ in range(a)]
    for i in range(m):
        for j in range(a):
            for k in range(b):
                R[j][i*b + k] = Q[i][j][k]

    # Normalize columns
    for c in range(n):
        col = [R[j][c] for j in range(a)]
        mean = sum(col) / a
        var = sum((x - mean) ** 2 for x in col) / a
        std = var ** 0.5
        if std == 0:
            for j in range(a):
                R[j][c] = 0.0
        else:
            for j in range(a):
                R[j][c] = (col[j] - mean) / std

    def fmt(x):
        r = round(x, 4)
        if r == 0:
            r = 0.0
        return "%.4f" % r

    header = " ".join("feature_%d" % i for i in range(n))
    print(header)
    for j in range(a):
        print(" ".join(fmt(R[j][c]) for c in range(n)))

if __name__ == "__main__":
    main()

