import sys, math

def compute_stats(arr):
    n = len(arr)
    if n == 0:
        return float('nan'), float('nan'), float('nan')
    mean = sum(arr) / n
    sorted_arr = sorted(arr)
    if n % 2 == 1:
        median = sorted_arr[n // 2]
    else:
        median = (sorted_arr[n // 2 - 1] + sorted_arr[n // 2]) / 2
    variance = sum((x - mean) ** 2 for x in arr) / n
    std = math.sqrt(variance)
    return mean, median, std

def main():
    data = sys.stdin.read().split('\n')
    line1 = data[0] if len(data) > 0 else ''
    line2 = data[1] if len(data) > 1 else ''

    arr1 = [float(x) for x in line1.split()] if line1.strip() != '' else []
    arr2 = [float(x) for x in line2.split()] if line2.strip() != '' else []

    mean1, median1, std1 = compute_stats(arr1)
    mean2, median2, std2 = compute_stats(arr2)

    def fmt(v):
        return "{:.4f}".format(v)

    print("Mean {} {}".format(fmt(mean1), fmt(mean2)))
    print("Median {} {}".format(fmt(median1), fmt(median2)))
    print("Standard Deviation {} {}".format(fmt(std1), fmt(std2)))

if __name__ == '__main__':
