import sys
import csv
from html.parser import HTMLParser


class TableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.table_stack = []
        self.rows = []
        self.cur_row = None
        self.cur_cell = None

    def in_target(self):
        return bool(self.table_stack) and self.table_stack[-1]

    def _close_cell(self):
        if self.cur_cell is not None:
            if self.cur_row is not None:
                self.cur_row.append(''.join(self.cur_cell))
            self.cur_cell = None

    def _close_row(self):
        self._close_cell()
        if self.cur_row is not None:
            self.rows.append(self.cur_row)
            self.cur_row = None

    def handle_starttag(self, tag, attrs):
        t = tag.lower()
        if t == 'table':
            cls = None
            for k, v in attrs:
                if k.lower() == 'class':
                    cls = v
            self.table_stack.append(cls == 'data-table')
        elif t == 'tr':
            if self.in_target():
                self._close_row()
                self.cur_row = []
        elif t == 'td':
            if self.in_target() and self.cur_row is not None:
                self._close_cell()
                self.cur_cell = []

    def handle_endtag(self, tag):
        t = tag.lower()
        if t == 'td':
            if self.in_target():
                self._close_cell()
        elif t == 'tr':
            if self.in_target():
                self._close_row()
        elif t == 'table':
            if self.in_target():
                self._close_row()
            if self.table_stack:
                self.table_stack.pop()

    def handle_data(self, data):
        if self.cur_cell is not None:
            self.cur_cell.append(data)

    def handle_entityref(self, name):
        # only reached if convert_charrefs is False; kept for safety
        if self.cur_cell is not None:
            import html as _html
            self.cur_cell.append(_html.unescape('&' + name + ';'))

    def handle_charref(self, name):
        if self.cur_cell is not None:
            import html as _html
            self.cur_cell.append(_html.unescape('&#' + name + ';'))


def main():
    data = sys.stdin.read()
    p = TableParser()
    try:
        p.feed(data)
        p.close()
    except Exception:
        pass
    # flush any dangling state
    p._close_row()
    rows = p.rows
    if not rows:
        return
    w = csv.writer(sys.stdout, lineterminator='\n')
    for r in rows:
        w.writerow(r)


main()

