            # skip completely empty trailing lines
            continue
        parts = line.split(',')
        if len(parts) < len(header):
            # pad if necessary, though spec doesn't require
            parts = parts + [''] * (len(header) - len(parts))
        rows.append(parts)
    if not rows:
        return
