import sys, re, csv, io
import pandas as pd

def main():
    data = sys.stdin.read()
    lines = data.splitlines()
    if not lines:
        return
    header_line = lines[0]
    columns = next(csv.reader([header_line]))

    if 'UnicodeString' not in columns:
        print('KeyError')
        return

    df = pd.read_csv(io.StringIO(data), dtype=str, keep_default_na=False)

    if df.empty:
        print(header_line)
        return

    def is_number(s):
        s = s.strip()
        if s == '':
            return False
        try:
            float(s)
            return True
        except ValueError:
            return False

    col = df['UnicodeString']
    if col.apply(is_number).any():
        print('TypeError')
        return

    def decode(s):
        return re.sub(r'\\u([0-9a-fA-F]{4})', lambda m: chr(int(m.group(1), 16)), s)

    df['UnicodeString'] = col.apply(decode)

    out = io.StringIO()
    writer = csv.writer(out, lineterminator='\n')
    for _, row in df.iterrows():
        writer.writerow([row[c] for c in columns])

    sys.stdout.write(header_line + '\n')
    sys.stdout.write(out.getvalue())

if __name__ == '__main__':
    main()
